import React, { useState, useEffect } from 'react';
import { getUsername } from '../../keycloak';
import './Questions.css'; // Стили для вопросов

const Questions = () => {
    const [questions, setQuestions] = useState([]);
    const [newQuestion, setNewQuestion] = useState('');
    const [answerText, setAnswerText] = useState({});
    const currentUser = getUsername();

    // Получаем роль из localStorage (от переключателя)
    const demoRole = localStorage.getItem('demoRole');
    const isAdmin = demoRole === 'admin';

    // Загружаем вопросы из localStorage
    useEffect(() => {
        const savedQuestions = localStorage.getItem('userQuestions');
        if (savedQuestions) {
            const allQuestions = JSON.parse(savedQuestions);

            // Если не админ - показываем только свои вопросы
            if (!isAdmin) {
                const myQuestions = allQuestions.filter(q => q.author === currentUser);
                setQuestions(myQuestions);
            } else {
                setQuestions(allQuestions);
            }
        } else {
            // Примеры вопросов для демонстрации
            const initialQuestions = [
                {
                    id: 1,
                    question: 'Как зарегистрироваться на событие?',
                    answer: 'Перейдите во вкладку "События", выберите интересующее событие и нажмите кнопку "Записаться".',
                    author: 'Анна',
                    date: '2025-03-20',
                    isAnswered: true,
                    answeredBy: 'Admin',
                    answerDate: '2025-03-21'
                },
                {
                    id: 2,
                    question: 'Где найти записи эфиров?',
                    answer: 'Все записи эфиров находятся в ленте "Главная" в разделе аудио.',
                    author: 'Михаил',
                    date: '2025-03-19',
                    isAnswered: true,
                    answeredBy: 'Admin',
                    answerDate: '2025-03-20'
                },
                {
                    id: 3,
                    question: 'Когда будут новые тренировки?',
                    answer: '',
                    author: currentUser,
                    date: new Date().toISOString().split('T')[0],
                    isAnswered: false
                }
            ];
            localStorage.setItem('userQuestions', JSON.stringify(initialQuestions));

            if (!isAdmin) {
                const myQuestions = initialQuestions.filter(q => q.author === currentUser);
                setQuestions(myQuestions);
            } else {
                setQuestions(initialQuestions);
            }
        }
    }, [isAdmin, currentUser]);

    // Сохраняем вопросы при изменении
    useEffect(() => {
        if (questions.length > 0) {
            const allQuestions = JSON.parse(localStorage.getItem('userQuestions') || '[]');

            // Обновляем существующие вопросы
            const updatedQuestions = allQuestions.map(q => {
                const updated = questions.find(uq => uq.id === q.id);
                return updated || q;
            });

            // Добавляем новые вопросы
            const newQuestions = questions.filter(q => !allQuestions.find(aq => aq.id === q.id));

            localStorage.setItem('userQuestions', JSON.stringify([...updatedQuestions, ...newQuestions]));
        }
    }, [questions]);

    const handleAskQuestion = () => {
        if (!newQuestion.trim()) {
            alert('Введите ваш вопрос');
            return;
        }

        const question = {
            id: Date.now(),
            question: newQuestion.trim(),
            answer: '',
            author: currentUser,
            date: new Date().toISOString().split('T')[0],
            isAnswered: false
        };

        // Получаем все вопросы из localStorage
        const allQuestions = JSON.parse(localStorage.getItem('userQuestions') || '[]');
        const updatedAllQuestions = [question, ...allQuestions];
        localStorage.setItem('userQuestions', JSON.stringify(updatedAllQuestions));

        // Обновляем состояние
        setQuestions([question, ...questions]);
        setNewQuestion('');
        alert('Ваш вопрос отправлен! Ответ появится в ближайшее время.');
    };

    const handleAnswerQuestion = (questionId) => {
        if (!isAdmin) {
            alert('Только администратор может отвечать на вопросы');
            return;
        }

        const answer = answerText[questionId];
        if (!answer || !answer.trim()) {
            alert('Введите ответ');
            return;
        }

        // Получаем все вопросы
        const allQuestions = JSON.parse(localStorage.getItem('userQuestions') || '[]');
        const updatedAllQuestions = allQuestions.map(q =>
            q.id === questionId
                ? {
                    ...q,
                    answer: answer.trim(),
                    isAnswered: true,
                    answeredBy: currentUser,
                    answerDate: new Date().toISOString().split('T')[0]
                }
                : q
        );

        localStorage.setItem('userQuestions', JSON.stringify(updatedAllQuestions));

        // Обновляем текущее состояние
        setQuestions(questions.map(q =>
            q.id === questionId
                ? {
                    ...q,
                    answer: answer.trim(),
                    isAnswered: true,
                    answeredBy: currentUser,
                    answerDate: new Date().toISOString().split('T')[0]
                }
                : q
        ));

        setAnswerText({ ...answerText, [questionId]: '' });
        alert('Ответ сохранен');
    };

    const handleDeleteQuestion = (questionId) => {
        if (!isAdmin) {
            alert('Только администратор может удалять вопросы');
            return;
        }

        if (window.confirm('Удалить этот вопрос?')) {
            const allQuestions = JSON.parse(localStorage.getItem('userQuestions') || '[]');
            const updatedAllQuestions = allQuestions.filter(q => q.id !== questionId);
            localStorage.setItem('userQuestions', JSON.stringify(updatedAllQuestions));

            setQuestions(questions.filter(q => q.id !== questionId));
        }
    };

    return (
        <div className="help-center">
            <div className="help-header">
                <h2>❓ Вопросы и ответы</h2>
                <p>
                    {isAdmin
                        ? '👑 Режим администратора: вы можете отвечать на все вопросы пользователей'
                        : '💬 Ваши вопросы (видны только вам). Администратор ответит в ближайшее время.'
                    }
                </p>
            </div>

            <div className="ask-section">
                <h3>💬 Задать вопрос</h3>
                <div className="ask-description">
                    <p>Напишите свой вопрос, и администраторы ответят вам в ближайшее время.</p>
                </div>

                <div className="ask-form">
                    <textarea
                        className="question-input"
                        placeholder="Введите ваш вопрос здесь..."
                        value={newQuestion}
                        onChange={(e) => setNewQuestion(e.target.value)}
                        rows="4"
                    />
                    <button
                        className="submit-button"
                        onClick={handleAskQuestion}
                    >
                        📤 Отправить вопрос
                    </button>
                </div>
            </div>

            <div className="faq-section">
                <h3>
                    {isAdmin
                        ? `📋 Все вопросы пользователей (${questions.length})`
                        : `📋 Мои вопросы (${questions.length})`
                    }
                </h3>
                <div className="faq-list">
                    {questions.length === 0 ? (
                        <div className="no-questions">
                            <p>❓ {isAdmin ? 'Пока нет вопросов от пользователей' : 'У вас пока нет вопросов'}</p>
                            {!isAdmin && <p className="hint-text">Задайте свой первый вопрос выше! ✍️</p>}
                        </div>
                    ) : (
                        questions.map((q) => (
                            <div key={q.id} className="faq-item">
                                <div className="faq-question">
                                    <div className="question-header">
                                        <strong>❓ {q.question}</strong>
                                        {isAdmin && (
                                            <button
                                                className="delete-question-btn"
                                                onClick={() => handleDeleteQuestion(q.id)}
                                                title="Удалить вопрос"
                                            >
                                                🗑️
                                            </button>
                                        )}
                                    </div>
                                    <div className="question-meta">
                                        <span>👤 {q.author}</span>
                                        <span>📅 {q.date}</span>
                                        {q.isAnswered && <span className="answered-badge">✅ Ответ дан</span>}
                                        {!q.isAnswered && <span className="pending-badge">⏳ Ожидает ответа</span>}
                                    </div>
                                </div>

                                {q.isAnswered ? (
                                    <div className="faq-answer">
                                        <strong>📝 Ответ:</strong>
                                        <p>{q.answer}</p>
                                        <div className="answer-meta">
                                            <span>👨‍💼 {q.answeredBy}</span>
                                            <span>📅 {q.answerDate}</span>
                                        </div>
                                    </div>
                                ) : (
                                    isAdmin && (
                                        <div className="answer-form">
                                            <textarea
                                                className="answer-input"
                                                placeholder="Введите ответ на вопрос..."
                                                value={answerText[q.id] || ''}
                                                onChange={(e) => setAnswerText({ ...answerText, [q.id]: e.target.value })}
                                                rows="3"
                                            />
                                            <button
                                                className="answer-submit"
                                                onClick={() => handleAnswerQuestion(q.id)}
                                            >
                                                ✍️ Ответить
                                            </button>
                                        </div>
                                    )
                                )}
                            </div>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
};

export default Questions;
